package Lecture1;

public class DivisibleByBoth5and11 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int num=110;
		if (num%5==0 && num%11==0) {
			System.out.println("Divisible by both 5 and 11");
			
		}
		else {
			System.out.println("Not divisible by both 5 and 11");
		}

	}

}
